use serde_json::{json,Value};use crate::monet::Scheme;
#[derive(Clone,Copy,Debug,PartialEq,Eq,serde::Serialize,serde::Deserialize)]pub enum Source{Content,System,Custom}
impl Source{pub fn parse(v:&str)->Self{match v{"System"=>Self::System,"Custom"=>Self::Custom,_=>Self::Content}}pub fn key(self)->&'static str{match self{Self::Content=>"Content",Self::System=>"System",Self::Custom=>"Custom"}}}
#[derive(Clone,Copy,Debug,PartialEq,serde::Serialize,serde::Deserialize)]pub struct Roles{pub primary:u32,pub on_primary:u32,pub primary_container:u32,pub on_primary_container:u32,pub secondary:u32,pub on_secondary:u32,pub secondary_container:u32,pub on_secondary_container:u32,pub tertiary:u32,pub on_tertiary:u32,pub tertiary_container:u32,pub on_tertiary_container:u32,pub error:u32,pub on_error:u32,pub error_container:u32,pub on_error_container:u32,pub surface:u32,pub on_surface:u32,pub surface_dim:u32,pub surface_bright:u32,pub surface_container_lowest:u32,pub surface_container_low:u32,pub surface_container:u32,pub surface_container_high:u32,pub surface_container_highest:u32,pub on_surface_variant:u32,pub outline:u32,pub outline_variant:u32,pub inverse_surface:u32,pub inverse_on_surface:u32,pub inverse_primary:u32,pub scrim:u32,pub surface_tint:u32,pub primary_fixed:u32,pub primary_fixed_dim:u32,pub on_primary_fixed:u32,pub on_primary_fixed_variant:u32,pub secondary_fixed:u32,pub secondary_fixed_dim:u32,pub on_secondary_fixed:u32,pub on_secondary_fixed_variant:u32,pub tertiary_fixed:u32,pub tertiary_fixed_dim:u32,pub on_tertiary_fixed:u32,pub on_tertiary_fixed_variant:u32,}
#[derive(Clone,Copy,Debug,serde::Serialize,serde::Deserialize)]pub struct Resolved{pub requested:Source,pub used:Source,pub seed:u32,pub fallback:bool,pub roles:Roles}
#[derive(Default,Clone,Copy,Debug,serde::Serialize,serde::Deserialize)]pub struct SeedMotion{from:u32,target:u32,at:f64,ready:bool}
#[derive(Default,serde::Serialize,serde::Deserialize)]pub struct RoleMotion{from:Option<Roles>,target:Option<Roles>,at:f64}
fn request<T:serde::de::DeserializeOwned>(method:&str,args:Value)->T{serde_json::from_value(dotisle_module_api::call("themes",method,args).expect("theme module unavailable")).expect("theme module response schema")}
pub fn roles(seed:u32,dark:bool,content:bool,high_contrast:bool)->Roles{request("roles",json!({"seed":seed,"dark":dark,"content":content,"high_contrast":high_contrast}))}
pub fn resolve(requested:Source,content:Option<u32>,system:Option<u32>,custom:u32,dark:bool,high_contrast:bool)->Resolved{request("resolve",json!({"requested":requested,"content":content,"system":system,"custom":custom,"dark":dark,"high":high_contrast}))}
pub fn resolve_center(requested:Source,content:Option<u32>,system:Option<u32>,custom:u32,dark:bool,high:bool)->Resolved{request("resolve_center",json!({"requested":requested,"content":content,"system":system,"custom":custom,"dark":dark,"high":high}))}
pub fn scheme(seed:u32,dark:bool)->Scheme{request("scheme",json!({"seed":seed,"dark":dark}))}
impl Roles{pub fn mix(self,other:Self,t:f64)->Self{request("roles.mix",json!({"self":self,"other":other,"t":t}))}pub fn ui(self)->Scheme{request("roles.ui",json!({"self":self}))}}
impl SeedMotion{pub fn update(&mut self,target:u32,now:f64,animate:bool)->bool{let v:Value=request("SeedMotion.update",json!({"state":self,"target":target,"now":now,"animate":animate}));*self=serde_json::from_value(v["state"].clone()).expect("motion state");v["result"]==true}pub fn sample(&self,now:f64)->u32{request("SeedMotion.sample",json!({"state":self,"now":now}))}pub fn moving(&self,now:f64)->bool{request("SeedMotion.moving",json!({"state":self,"now":now}))}}
impl RoleMotion{pub fn update(&mut self,target:Roles,now:f64,animate:bool)->bool{let v:Value=request("RoleMotion.update",json!({"state":self,"target":target,"now":now,"animate":animate}));*self=serde_json::from_value(v["state"].clone()).expect("motion state");v["result"]==true}pub fn sample(&self,now:f64)->Roles{request("RoleMotion.sample",json!({"state":self,"now":now}))}pub fn moving(&self,now:f64)->bool{request("RoleMotion.moving",json!({"state":self,"now":now}))}}
